package com.bank.ageband;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class AgeBandDemo {
    private static final Logger log = Logger.getLogger("AgeBand");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Amit", 28),
            new Employee("Rajesh", 34),
            new Employee("Priya", 41),
            new Employee("Vikram", 55));
        AgeBandService service = new AgeBandService();

        Map<String, List<String>> bands = service.byAgeBand(staff);
        bands.forEach((band, names) -> log.info(() -> band + " → " + names));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final int age;
    Employee(String name, int age) { this.name = name; this.age = age; }
    String getName() { return name; }
    int getAge() { return age; }
}

// ─── Would be in service/AgeBandService.java ───
class AgeBandService {
    // custom classifier: age → band label
    private String band(int age) {
        if (age < 30) return "20-29";
        if (age < 40) return "30-39";
        if (age < 50) return "40-49";
        return "50+";
    }

    Map<String, List<String>> byAgeBand(List<Employee> staff) {
        return staff.stream()
            .collect(groupingBy(
                e -> band(e.getAge()),                  // custom classifier
                TreeMap::new,                           // stable sorted band order
                mapping(Employee::getName, toList())));  // store names per band
    }
}
